import { createSignal, onCleanup } from "solid-js";
import { isServer } from "@solidjs/web";
import * as web from "@solidjs/web";

const noop = () => {};

// `createRAF`'s shape (`@solid-primitives/raf@4.0.0-next.2` `dist/index.js`),
// its frame loop reduced to a callback: an `isServer` early return of a
// complete literal, then the live factory's one return.
function createLoop(callback) {
	if (isServer) return [
		() => false,
		noop,
		noop
	];
	const [running, setRunning] = createSignal(false, { ownedWrite: true });
	const start = () => {
		if (running()) return;
		setRunning(true);
		callback();
	};
	const stop = () => {
		setRunning(false);
	};
	onCleanup(stop);
	return [
		running,
		start,
		stop
	];
}

// The server arm returns closures the factory declares, so under a server
// host its slot resolves, and reads nothing.
function createIdleLoop(callback) {
	const idle = () => {};
	if (isServer) return [() => false, idle, idle];
	const [running, setRunning] = createSignal(false, { ownedWrite: true });
	const start = () => {
		if (running()) return;
		setRunning(true);
		callback();
	};
	return [running, start, idle];
}

// The same guard as a block.
function createBlockLoop(callback) {
	if (isServer) {
		return [() => false, noop, noop];
	}
	const [running, setRunning] = createSignal(false, { ownedWrite: true });
	const start = () => {
		if (running()) return;
		setRunning(true);
		callback();
	};
	return [running, start, noop];
}

// The live factory inside the guard; the server return follows it.
function createClientLoop(callback) {
	if (!isServer) {
		const [running, setRunning] = createSignal(false, { ownedWrite: true });
		const start = () => {
			if (running()) return;
			setRunning(true);
			callback();
		};
		return [running, start, noop];
	}
	return [() => false, noop, noop];
}

// A guard no host decides: an ordinary parameter.
function createFlaggedLoop(flag, callback) {
	if (flag) return [() => false, noop, noop];
	const [running, setRunning] = createSignal(false, { ownedWrite: true });
	const start = () => {
		if (running()) return;
		setRunning(true);
		callback();
	};
	return [running, start, noop];
}

// A guard the host constant takes part in but does not decide.
function createEitherLoop(flag, callback) {
	if (isServer || flag) return [() => false, noop, noop];
	const [running, setRunning] = createSignal(false, { ownedWrite: true });
	const start = () => {
		if (running()) return;
		setRunning(true);
		callback();
	};
	return [running, start, noop];
}

// `isServer` read through a namespace import, which the fold does not bind.
function createNamespacedLoop(callback) {
	if (web.isServer) return [() => false, noop, noop];
	const [running, setRunning] = createSignal(false, { ownedWrite: true });
	const start = () => {
		if (running()) return;
		setRunning(true);
		callback();
	};
	return [running, start, noop];
}

export {
	createBlockLoop,
	createClientLoop,
	createEitherLoop,
	createFlaggedLoop,
	createIdleLoop,
	createLoop,
	createLoop as default,
	createNamespacedLoop
};
